type Router struct {
	http.Handler
	ds          model.DataStore
	sessionKeys *sessionKeys
	client      *Client
	apiKey      string
	secret      string
	stateSecret []byte
}

func NewRouter(ds model.DataStore) *Router {
	r := &Router{
		ds:          ds,
		apiKey:      conf.Server.LastFM.ApiKey,
		secret:      conf.Server.LastFM.Secret,
		sessionKeys: &sessionKeys{ds: ds},
	}
	r.Handler = r.routes()
	hc := &http.Client{
		Timeout: consts.DefaultHttpClientTimeOut,
	}
	r.client = NewClient(r.apiKey, r.secret, "en", hc)
	return r
}

func (s *Router) routes() http.Handler {
	r := chi.NewRouter()

	r.Group(func(r chi.Router) {
		r.Use(server.Authenticator(s.ds))
		r.Use(server.JWTRefresher)

		r.Get("/link", s.getLinkStatus)
		r.Get("/link/state", s.getLinkState)
		r.Delete("/link", s.unlink)
	})

	r.Get("/link/callback", s.callback)

	return r
}

type linkState struct {
	UserID  string `json:"userId"`
	Expires int64  `json:"expires"`
}

func (s *Router) linkStateSecret() []byte {
	if s.stateSecret != nil {
		return s.stateSecret
	}
	return auth.Secret
}

func (s *Router) signLinkState(userId string) string {
	payload, _ := json.Marshal(linkState{UserID: userId, Expires: time.Now().Add(10 * time.Minute).Unix()})
	mac := hmac.New(sha256.New, s.linkStateSecret())
	_, _ = mac.Write(payload)
	return base64.RawURLEncoding.EncodeToString(payload) + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
}

func (s *Router) parseLinkState(value string) (string, error) {
	parts := bytes.Split([]byte(value), []byte("."))
	if len(parts) != 2 {
		return "", errors.New("invalid link state")
	}
	if len(s.linkStateSecret()) == 0 {
		return "", errors.New("link state unavailable")
	}
	payload, err := base64.RawURLEncoding.DecodeString(string(parts[0]))
	if err != nil {
		return "", errors.New("invalid link state")
	}
	signature, err := base64.RawURLEncoding.DecodeString(string(parts[1]))
	if err != nil {
		return "", errors.New("invalid link state")
	}
	mac := hmac.New(sha256.New, s.linkStateSecret())
	_, _ = mac.Write(payload)
	if !hmac.Equal(signature, mac.Sum(nil)) {
		return "", errors.New("invalid link state")
	}
	var state linkState
	if json.Unmarshal(payload, &state) != nil || state.UserID == "" || time.Now().Unix() >= state.Expires {
		return "", errors.New("invalid link state")
	}
	return state.UserID, nil
}

func (s *Router) getLinkState(w http.ResponseWriter, r *http.Request) {
	user, ok := request.UserFrom(r.Context())
	if !ok {
		_ = rest.RespondWithError(w, http.StatusUnauthorized, "user not authenticated")
		return
	}
	if len(s.linkStateSecret()) == 0 {
		_ = rest.RespondWithError(w, http.StatusInternalServerError, "link state unavailable")
		return
	}
	_ = rest.RespondWithJSON(w, http.StatusOK, map[string]string{"state": s.signLinkState(user.ID)})
